CREATE TYPE "Role" AS ENUM ('USER', 'ADMIN');
CREATE TYPE "IPCategory" AS ENUM ('LOGO', 'ARTWORK', 'SOFTWARE', 'ALGORITHM', 'PHOTOGRAPHY', 'RESEARCH', 'DOCUMENT', 'MUSIC', 'DESIGN', 'WRITING', 'OTHER');
CREATE TYPE "BlockchainStatus" AS ENUM ('PENDING', 'CONFIRMED', 'FAILED', 'UNAVAILABLE');
CREATE TYPE "VerificationType" AS ENUM ('EXACT', 'LOGO_VISUAL');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "name" TEXT NOT NULL, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "role" "Role" NOT NULL DEFAULT 'USER', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "IPRegistration" ("id" TEXT PRIMARY KEY, "ipId" TEXT NOT NULL UNIQUE, "rootIpId" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT, "category" "IPCategory" NOT NULL, "creatorName" TEXT NOT NULL, "creatorId" TEXT NOT NULL REFERENCES "User"("id"), "sha256" TEXT NOT NULL UNIQUE, "storageKey" TEXT NOT NULL, "storageUrl" TEXT, "mimeType" TEXT NOT NULL, "fileSize" INTEGER NOT NULL, "license" TEXT NOT NULL, "tags" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], "version" INTEGER NOT NULL DEFAULT 1, "previousIpId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "blockchainTxHash" TEXT, "blockchainStatus" "BlockchainStatus" NOT NULL DEFAULT 'UNAVAILABLE', "contractAddress" TEXT, "blockchainError" TEXT);
CREATE TABLE "IPVersion" ("id" TEXT PRIMARY KEY, "registrationId" TEXT NOT NULL REFERENCES "IPRegistration"("id") ON DELETE CASCADE, "rootIpId" TEXT NOT NULL, "ipId" TEXT NOT NULL UNIQUE, "version" INTEGER NOT NULL, "previousIpId" TEXT, "sha256" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("rootIpId", "version"));
CREATE TABLE "LogoFingerprint" ("id" TEXT PRIMARY KEY, "ipRegistrationId" TEXT NOT NULL UNIQUE REFERENCES "IPRegistration"("id") ON DELETE CASCADE, "fingerprint" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "BlockchainTransaction" ("id" TEXT PRIMARY KEY, "ipRegistrationId" TEXT NOT NULL REFERENCES "IPRegistration"("id") ON DELETE CASCADE, "txHash" TEXT, "network" TEXT, "contractAddress" TEXT, "status" "BlockchainStatus" NOT NULL, "error" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "confirmedAt" TIMESTAMP(3));
CREATE TABLE "VerificationRecord" ("id" TEXT PRIMARY KEY, "type" "VerificationType" NOT NULL, "sha256" TEXT, "searchedById" TEXT REFERENCES "User"("id"), "matchedRegistrationId" TEXT REFERENCES "IPRegistration"("id"), "result" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY, "userId" TEXT REFERENCES "User"("id"), "action" TEXT NOT NULL, "details" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "RegistryCounter" ("id" INTEGER PRIMARY KEY, "value" INTEGER NOT NULL DEFAULT 0);
CREATE INDEX "IPRegistration_rootIpId_idx" ON "IPRegistration"("rootIpId"); CREATE INDEX "IPRegistration_category_idx" ON "IPRegistration"("category"); CREATE INDEX "IPRegistration_creatorId_idx" ON "IPRegistration"("creatorId"); CREATE INDEX "IPRegistration_createdAt_idx" ON "IPRegistration"("createdAt"); CREATE INDEX "IPVersion_rootIpId_idx" ON "IPVersion"("rootIpId"); CREATE INDEX "BlockchainTransaction_ipRegistrationId_idx" ON "BlockchainTransaction"("ipRegistrationId");
